/**
 * Writes the Dart side of a spec: model classes with `fromJson`/`toJson`,
 * enums, sealed unions and (for specs with unsigned operations) a client over
 * `../client/api_client.dart`.
 *
 * No `json_serializable`, no `build_runner`: the generated file is plain Dart,
 * so a consumer never runs a code generator of its own. Formatting is switched
 * off for the file (`dart format off`) because this generator, not the
 * formatter, is the thing that must be deterministic.
 */
import {
  camelCase,
  dartDoc,
  dartIdentifier,
  dartString,
  enumMemberName,
} from "./names.js";
import type { Decl, Operation, Param, Spec, Type } from "./spec.js";

export const DART_BANNER = (source: string): string =>
  `// @generated by @devdogsuga/sdk-spec from ${source} — do not edit by hand.\n// Run \`pnpm -F @devdogsuga/sdk-spec codegen\` after changing the spec.\n// dart format off\n// ignore_for_file: type=lint, unused_import\n`;

class Context {
  readonly byName = new Map<string, Decl>();
  readonly parentOf = new Map<string, string>();
  constructor(decls: Decl[]) {
    for (const decl of decls) this.byName.set(decl.name, decl);
    for (const decl of decls) {
      if (decl.kind !== "union") continue;
      for (const member of decl.members) {
        if (this.parentOf.has(member)) {
          throw new Error(`${member} belongs to two unions; Dart allows one`);
        }
        this.parentOf.set(member, decl.name);
      }
    }
  }

  decl(name: string): Decl {
    const decl = this.byName.get(name);
    if (!decl) throw new Error(`Unknown schema ${name}`);
    return decl;
  }
}

export function dartType(type: Type): string {
  switch (type.kind) {
    case "string":
      return type.format === "date-time" ? "DateTime" : "String";
    case "integer":
      return "int";
    case "number":
      return "double";
    case "boolean":
      return "bool";
    case "unknown":
      return "Object?";
    case "array":
      return `List<${dartType(type.item)}>`;
    case "record":
      return `Map<String, ${dartType(type.value)}>`;
    case "ref":
      return type.name;
    case "nullable": {
      const inner = dartType(type.inner);
      return inner.endsWith("?") ? inner : `${inner}?`;
    }
  }
}

function fromJson(type: Type, e: string, ctx: Context, depth = 0): string {
  switch (type.kind) {
    case "string":
      return type.format === "date-time"
        ? `DateTime.parse(${e} as String)`
        : `${e} as String`;
    case "integer":
      return `(${e} as num).toInt()`;
    case "number":
      return `(${e} as num).toDouble()`;
    case "boolean":
      return `${e} as bool`;
    case "unknown":
      return e;
    case "array": {
      const v = `x${depth}`;
      return `(${e} as List<dynamic>).map((${v}) => ${fromJson(type.item, v, ctx, depth + 1)}).toList()`;
    }
    case "record": {
      const v = `v${depth}`;
      return `(${e} as Map<String, dynamic>).map((k${depth}, ${v}) => MapEntry(k${depth}, ${fromJson(type.value, v, ctx, depth + 1)}))`;
    }
    case "ref": {
      const decl = ctx.decl(type.name);
      switch (decl.kind) {
        case "object":
        case "union":
          return `${decl.name}.fromJson(${e} as Map<String, dynamic>)`;
        case "enum":
          return `${decl.name}.fromJson(${e} as String)`;
        case "alias":
          return fromJson(decl.type, e, ctx, depth);
      }
      break;
    }
    case "nullable":
      return `${e} == null ? null : ${fromJson(type.inner, e, ctx, depth)}`;
  }
  throw new Error("unreachable");
}

/** True when the JSON form of a value is the Dart value itself. */
function isIdentity(type: Type, ctx: Context): boolean {
  switch (type.kind) {
    case "string":
      return type.format !== "date-time";
    case "integer":
    case "number":
    case "boolean":
    case "unknown":
      return true;
    case "array":
      return isIdentity(type.item, ctx);
    case "record":
      return isIdentity(type.value, ctx);
    case "ref": {
      const decl = ctx.decl(type.name);
      return decl.kind === "alias" ? isIdentity(decl.type, ctx) : false;
    }
    case "nullable":
      return isIdentity(type.inner, ctx);
  }
}

function toJson(type: Type, e: string, ctx: Context, depth = 0): string {
  if (isIdentity(type, ctx)) return e;
  switch (type.kind) {
    case "string":
      return `${e}.toIso8601String()`;
    case "array": {
      const v = `x${depth}`;
      return `${e}.map((${v}) => ${toJson(type.item, v, ctx, depth + 1)}).toList()`;
    }
    case "record": {
      const v = `v${depth}`;
      return `${e}.map((k${depth}, ${v}) => MapEntry(k${depth}, ${toJson(type.value, v, ctx, depth + 1)}))`;
    }
    case "ref": {
      const decl = ctx.decl(type.name);
      return decl.kind === "alias"
        ? toJson(decl.type, e, ctx, depth)
        : `${e}.toJson()`;
    }
    case "nullable":
      return `${e} == null ? null : ${toJson(type.inner, `${e}!`, ctx, depth)}`;
    default:
      return e;
  }
}

function emitObject(
  decl: Extract<Decl, { kind: "object" }>,
  ctx: Context,
): string {
  const parent = ctx.parentOf.get(decl.name);
  const lines: string[] = [];
  const objectDoc = dartDoc(decl.doc).trimEnd();
  if (objectDoc) lines.push(objectDoc);
  lines.push(`class ${decl.name}${parent ? ` extends ${parent}` : ""} {`);
  const params = decl.props.map((p) => ({
    p,
    field: dartIdentifier(p.name),
    nullable: !p.required || p.type.kind === "nullable",
  }));
  if (params.length === 0) {
    lines.push(`  const ${decl.name}();`);
  } else {
    lines.push(`  const ${decl.name}({`);
    for (const { p, field } of params) {
      lines.push(`    ${p.required ? "required " : ""}this.${field},`);
    }
    lines.push("  });");
  }
  lines.push("");
  for (const { p, field, nullable } of params) {
    const base = dartType(p.type);
    const type = nullable && !base.endsWith("?") ? `${base}?` : base;
    const doc = dartDoc(p.doc, "  ");
    if (doc) lines.push(doc.trimEnd());
    lines.push(`  final ${type} ${field};`);
  }
  lines.push("");
  lines.push(
    `  factory ${decl.name}.fromJson(Map<String, dynamic> json) => ${decl.name}(`,
  );
  for (const { p, field, nullable } of params) {
    const e = `json[${dartString(p.name)}]`;
    const type: Type =
      nullable && p.type.kind !== "nullable"
        ? { kind: "nullable", inner: p.type }
        : p.type;
    lines.push(`        ${field}: ${fromJson(type, e, ctx)},`);
  }
  lines.push("      );");
  lines.push("");
  if (parent) lines.push("  @override");
  lines.push("  Map<String, dynamic> toJson() => {");
  for (const { p, field, nullable } of params) {
    const optional = !p.required;
    const value = toJson(
      nullable && p.type.kind !== "nullable"
        ? { kind: "nullable", inner: p.type }
        : p.type,
      field,
      ctx,
    );
    const entry = `${dartString(p.name)}: ${value}`;
    if (optional) {
      const nonNull = toJson(
        p.type.kind === "nullable" ? p.type.inner : p.type,
        `${field}!`,
        ctx,
      );
      lines.push(
        `        if (${field} != null) ${dartString(p.name)}: ${nonNull},`,
      );
    } else {
      lines.push(`        ${entry},`);
    }
  }
  lines.push("      };");
  lines.push("}");
  return `${lines.filter((l, i) => !(l === "" && lines[i - 1] === "")).join("\n")}\n`;
}

function emitEnum(decl: Extract<Decl, { kind: "enum" }>): string {
  const seen = new Set<string>();
  const members = decl.values.map((value) => {
    const name = dartIdentifier(enumMemberName(value));
    if (seen.has(name)) {
      throw new Error(`${decl.name}: two values map to the Dart name ${name}`);
    }
    seen.add(name);
    return `  ${name}(${dartString(value)})`;
  });
  return `${dartDoc(decl.doc)}enum ${decl.name} {\n${members.join(",\n")};\n\n  const ${decl.name}(this.value);\n\n  /// The value on the wire.\n  final String value;\n\n  factory ${decl.name}.fromJson(String value) => values.firstWhere(\n        (e) => e.value == value,\n        orElse: () => throw FormatException('Unknown ${decl.name}: $value'),\n      );\n\n  String toJson() => value;\n}\n`;
}

function emitUnion(
  decl: Extract<Decl, { kind: "union" }>,
  ctx: Context,
): string {
  const lines: string[] = [];
  const doc = dartDoc(decl.doc).trimEnd();
  if (doc) lines.push(doc);
  lines.push(`sealed class ${decl.name} {`);
  lines.push(`  const ${decl.name}();`);
  lines.push("");
  lines.push(`  factory ${decl.name}.fromJson(Map<String, dynamic> json) {`);
  if (decl.discriminator) {
    const prop = decl.discriminator;
    lines.push(`    final tag = json[${dartString(prop)}];`);
    for (const memberName of decl.members) {
      const member = ctx.decl(memberName);
      if (member.kind !== "object") continue;
      const tagProp = member.props.find((p) => p.name === prop);
      if (tagProp?.type.kind !== "ref") continue;
      const tagDecl = ctx.decl(tagProp.type.name);
      if (tagDecl.kind !== "enum") continue;
      const values = tagDecl.values.map(dartString).join(", ");
      lines.push(
        `    if (const <String>{${values}}.contains(tag)) return ${memberName}.fromJson(json);`,
      );
    }
    lines.push(
      `    throw FormatException('Unknown ${decl.name} ${prop}: $tag');`,
    );
  } else {
    for (const memberName of decl.members) {
      lines.push(
        `    try {\n      return ${memberName}.fromJson(json);\n    } on Object {\n      // Try the next member.\n    }`,
      );
    }
    lines.push(`    throw FormatException('Not a ${decl.name}: $json');`);
  }
  lines.push("  }");
  lines.push("");
  lines.push("  Map<String, dynamic> toJson();");
  lines.push("}");
  return `${lines.join("\n")}\n`;
}

function emitDeclDart(decl: Decl, ctx: Context): string {
  switch (decl.kind) {
    case "object":
      return emitObject(decl, ctx);
    case "enum":
      return emitEnum(decl);
    case "union":
      return emitUnion(decl, ctx);
    case "alias":
      return `${dartDoc(decl.doc)}typedef ${decl.name} = ${dartType(decl.type)};\n`;
  }
}

function operationParams(op: Operation): Param[] {
  return op.params.filter((p) => p.in !== "header");
}

function emitOperation(op: Operation, ctx: Context): string {
  const params = operationParams(op).map((p) => ({
    p,
    name: dartIdentifier(camelCase(p.name)),
  }));
  const requiredFirst = [...params].sort(
    (a, b) => Number(b.p.required) - Number(a.p.required),
  );
  const sig =
    params.length === 0
      ? ""
      : `{${requiredFirst
          .map(({ p, name }) => {
            const type = dartType(p.type);
            return p.required
              ? `required ${type} ${name}`
              : `${type.endsWith("?") ? type : `${type}?`} ${name}`;
          })
          .join(", ")}}`;
  const result = op.success ? dartType(op.success.type) : "void";
  const doc = dartDoc(
    [op.summary, op.doc].filter(Boolean).join("\n\n") || undefined,
    "  ",
  );
  const pathExpr = op.path.includes("{")
    ? `'${op.path.replace(/\{([^}]+)\}/g, (_m, n: string) => `\${Uri.encodeComponent(${dartIdentifier(camelCase(n))}.toString())}`)}'`
    : dartString(op.path);
  const query = params.filter(({ p }) => p.in === "query");
  const queryExpr =
    query.length > 0
      ? `{\n${query
          .map(({ p, name }) =>
            p.required
              ? `        ${dartString(p.name)}: ${name}.toString(),`
              : `        if (${name} != null) ${dartString(p.name)}: ${name}.toString(),`,
          )
          .join("\n")}\n      }`
      : "const {}";
  const body = op.success
    ? `    final json = await _api.send('${op.method.toUpperCase()}', ${pathExpr}, query: ${queryExpr});\n    return ${fromJson(op.success.type, "json", ctx)};`
    : `    await _api.send('${op.method.toUpperCase()}', ${pathExpr}, query: ${queryExpr});`;
  return `${doc}  Future<${result}> ${op.id}(${sig}) async {\n${body}\n  }\n`;
}

export interface DartOutputOptions {
  source: string;
  /** `Catalog` gives `CatalogClient`. */
  clientName?: string;
  /** Declarations another generated file already defines. */
  skipDecls?: ReadonlySet<string>;
  /** Imports for the declarations skipped above (relative to the file). */
  imports?: readonly string[];
}

export function emitDart(spec: Spec, options: DartOutputOptions): string {
  const ctx = new Context(spec.decls);
  const clientOps = spec.ops.filter((op) => op.client);
  const name = options.clientName;
  const parts: string[] = [DART_BANNER(options.source)];
  const imports = [...(options.imports ?? [])].map((i) => `import '${i}';`);
  if (name && clientOps.length > 0) {
    imports.unshift(
      `import 'package:http/http.dart' as http;`,
      `import '../client/api_client.dart';`,
    );
  }
  if (imports.length > 0) parts.push(`${imports.join("\n")}\n`);
  if (spec.servers.length > 0 && name) {
    const entries = spec.servers
      .map((s) => `  ${dartString(camelCase(s.key))}: ${dartString(s.url)},`)
      .join("\n");
    parts.push(
      `/// The servers the spec lists.\nconst ${camelCase(name)}Servers = <String, String>{\n${entries}\n};\n`,
    );
  }
  for (const decl of spec.decls) {
    if (options.skipDecls?.has(decl.name)) continue;
    parts.push(emitDeclDart(decl, ctx));
  }
  if (name && clientOps.length > 0) {
    const methods = clientOps.map((op) => emitOperation(op, ctx)).join("\n");
    parts.push(
      `/// A client for the ${name} API. [baseUrl] is required: read it from the\n/// environment, never hard-code a server.\nclass ${name}Client {\n  ${name}Client({\n    required String baseUrl,\n    http.Client? httpClient,\n    String? clientName,\n  }) : _api = ApiClient(\n          baseUrl: baseUrl,\n          httpClient: httpClient,\n          clientName: clientName,\n        );\n\n  final ApiClient _api;\n\n  /// Closes the underlying HTTP client if this client created it.\n  void close() => _api.close();\n\n${methods}}\n`,
    );
  }
  return parts.join("\n");
}

/** Declarations only (no client): for schema files that are not OpenAPI. */
export function emitDartModels(decls: Decl[], source: string): string {
  const ctx = new Context(decls);
  return [DART_BANNER(source), ...decls.map((d) => emitDeclDart(d, ctx))].join(
    "\n",
  );
}
